final class SupplierPerformanceController
{
    private function tenant(): string { return (string) app(TenantContext::class)->id(); }
    private function scope(Request $r, AuthorizationService $a, ?string $company = null): array
    {
        $t=$this->tenant();
        if($company){abort_unless($a->allows($r->user(),$t,'procurement.manage',$company),403);return [$t,[$company]];}
        $ids=$a->accessibleCompanyIds($r->user(),$t,'procurement.manage'); abort_unless($ids===null||$ids!==[],403);
        return [$t,$ids];
    }
    private function supplier(Request $r, Supplier $s, AuthorizationService $a, ?string $company=null): void
    { abort_unless($s->tenant_id===$this->tenant(),404); $this->scope($r,$a,$company?:$s->company_id); abort_unless(!$company||$s->company_id===null||$s->company_id===$company,404); }
    public function summary(Request $r, AuthorizationService $a): JsonResponse
    {
        [$t,$ids]=$this->scope($r,$a,$r->string('company_id')->toString()?:null);
        $suppliers=Supplier::where('tenant_id',$t)->when(is_array($ids),fn($q)=>$q->whereIn('company_id',$ids));
        $evaluations=SupplierPerformanceEvaluation::where('tenant_id',$t)->when(is_array($ids),fn($q)=>$q->whereIn('company_id',$ids));
        $reviews=SupplierComplianceReview::where('tenant_id',$t)->when(is_array($ids),fn($q)=>$q->whereIn('company_id',$ids));
        return response()->json(['data'=>['evaluated_suppliers'=>(clone $evaluations)->where('status','approved')->distinct('supplier_id')->count('supplier_id'),'on_time_delivery_rate'=>$this->aggregate($t,$ids,'on_time_delivery'),'quality_acceptance_rate'=>$this->aggregate($t,$ids,'quality_acceptance'),'suppliers_under_review'=>(clone $evaluations)->whereIn('status',['draft','pending_review'])->distinct('supplier_id')->count('supplier_id'),'high_risk_suppliers'=>SupplierRiskAssessment::where('tenant_id',$t)->when(is_array($ids),fn($q)=>$q->whereIn('company_id',$ids))->where('status','approved')->whereIn('final_level',['high','critical'])->distinct('supplier_id')->count('supplier_id'),'expiring_compliance_documents'=>SupplierDocument::where('tenant_id',$t)->when(is_array($ids),fn($q)=>$q->whereIn('company_id',$ids))->whereNotNull('expiry_date')->whereBetween('expiry_date',[now()->toDateString(),now()->addDays(90)->toDateString()])->count(),'non_compliant_suppliers'=>(clone $reviews)->whereIn('status',['non_compliant','action_required'])->count(),'supplier_count'=>$suppliers->count()]]);
    }
    public function performance(Request $r, AuthorizationService $a): JsonResponse
    {
        [$t,$ids]=$this->scope($r,$a,$r->string('company_id')->toString()?:null);$q=SupplierPerformanceEvaluation::where('tenant_id',$t)->with(['supplier','metrics'])->when(is_array($ids),fn($x)=>$x->whereIn('company_id',$ids))->when($r->filled('supplier_id'),fn($x)=>$x->where('supplier_id',$r->string('supplier_id')))->when($r->filled('status'),fn($x)=>$x->where('status',$r->string('status')))->latest('period_to');return response()->json(['data'=>$q->paginate(min(max($r->integer('per_page',25),10),100)),'methodology'=>'Scores are generated only from eligible posted/approved purchasing records and unavailable metrics are not treated as zero.']);
    }
    public function storePolicy(Request $r, AuthorizationService $a, AuditLogger $audit): JsonResponse
    {
        $d=$r->validate(['company_id'=>'required|uuid','name'=>'required|string|max:200','effective_from'=>'required|date','effective_until'=>'nullable|date|after_or_equal:effective_from','frequency'=>'required|in:monthly,quarterly,yearly','minimum_sample_size'=>'required|integer|min:1|max:100000','delivery_weight'=>'required|numeric|min:0|max:100','quality_weight'=>'required|numeric|min:0|max:100','price_weight'=>'required|numeric|min:0|max:100','fulfillment_weight'=>'required|numeric|min:0|max:100','responsiveness_weight'=>'required|numeric|min:0|max:100','rating_thresholds'=>'nullable|array','missing_data_policy'=>'required|in:unavailable,reweight']);
        $this->scope($r,$a,$d['company_id']);$sum=(float)$d['delivery_weight']+(float)$d['quality_weight']+(float)$d['price_weight']+(float)$d['fulfillment_weight'];$sum+=(float)$d['responsiveness_weight'];abort_unless(abs($sum-100)<0.0001,422,'Performance weights must total 100%.');$overlap=SupplierPerformancePolicy::where('tenant_id',$this->tenant())->where('company_id',$d['company_id'])->where('is_active',true)->whereDate('effective_from','<=',$d['effective_until']??'2999-12-31')->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',$d['effective_from']))->exists();abort_if($overlap,422,'The effective period overlaps an active policy.');$p=SupplierPerformancePolicy::create([...$d,'tenant_id'=>$this->tenant(),'is_active'=>false,'created_by'=>$r->user()->id,'version'=>1]);$audit->record($r,'supplier_performance_policy.created',$this->tenant(),$p);return response()->json(['data'=>$p],201);
    }
    public function createEvaluation(Request $r, AuthorizationService $a, ProcurementNumberService $numbers, AuditLogger $audit): JsonResponse
    {
        $d=$r->validate(['company_id'=>'required|uuid','supplier_id'=>'required|uuid','period_from'=>'required|date','period_to'=>'required|date|after_or_equal:period_from','policy_id'=>'nullable|uuid']);
        $this->scope($r,$a,$d['company_id']);$s=Supplier::where('tenant_id',$this->tenant())->whereKey($d['supplier_id'])->firstOrFail();abort_unless($s->company_id===null||$s->company_id===$d['company_id'],422);$policy=SupplierPerformancePolicy::where('tenant_id',$this->tenant())->where('company_id',$d['company_id'])->where('is_active',true)->when($d['policy_id']??null,fn($q)=>$q->whereKey($d['policy_id']))->first();abort_unless($policy,422,'An active performance policy is required.');$metrics=$this->metricData($s->id,$d['company_id'],$d['period_from'],$d['period_to']);$e=DB::transaction(function()use($d,$policy,$metrics,$numbers,$r){$e=SupplierPerformanceEvaluation::create([...$d,'tenant_id'=>$this->tenant(),'policy_id'=>$policy->id,'number'=>$numbers->makeFor('SPE',$this->tenant(),$d['company_id'],null),'methodology_version'=>'policy-'.$policy->version,'status'=>'draft','created_by'=>$r->user()->id]);foreach($metrics as $metric=>$row)SupplierPerformanceMetricResult::create(['tenant_id'=>$this->tenant(),'evaluation_id'=>$e->id,'metric'=>$metric,...$row]);return $e;});$audit->record($r,'supplier_performance_evaluation.created',$this->tenant(),$e);return response()->json(['data'=>$e->load(['supplier','policy','metrics'])],201);
    }
    public function submitEvaluation(Request $r,SupplierPerformanceEvaluation $evaluation,AuthorizationService $a,AuditLogger $audit):JsonResponse{abort_unless($evaluation->tenant_id===$this->tenant(),404);$this->scope($r,$a,$evaluation->company_id);abort_unless($evaluation->status==='draft',422);$evaluation->update(['status'=>'pending_review','submitted_at'=>now()]);$audit->record($r,'supplier_performance_evaluation.submitted',$this->tenant(),$evaluation);return response()->json(['data'=>$evaluation->fresh('metrics')]);}
    public function approveEvaluation(Request $r,SupplierPerformanceEvaluation $evaluation,AuthorizationService $a,AuditLogger $audit):JsonResponse{abort_unless($evaluation->tenant_id===$this->tenant(),404);$this->scope($r,$a,$evaluation->company_id);abort_unless($evaluation->status==='pending_review',422);abort_unless($evaluation->created_by!==$r->user()->id,403,'The evaluator cannot approve the same evaluation.');$d=$r->validate(['reviewer_comments'=>'nullable|string|max:5000']);$evaluation->update(['status'=>'approved','reviewer_id'=>$r->user()->id,'reviewer_comments'=>$d['reviewer_comments']??null,'approved_at'=>now()]);$audit->record($r,'supplier_performance_evaluation.approved',$this->tenant(),$evaluation);return response()->json(['data'=>$evaluation->fresh('metrics')]);}
    public function risks(Request $r,AuthorizationService $a):JsonResponse{[$t,$ids]=$this->scope($r,$a,$r->string('company_id')->toString()?:null);$q=SupplierRiskAssessment::where('tenant_id',$t)->with('supplier')->when(is_array($ids),fn($x)=>$x->whereIn('company_id',$ids))->when($r->filled('risk_level'),fn($x)=>$x->where('final_level',$r->string('risk_level')))->latest();return response()->json(['data'=>$q->paginate(min(max($r->integer('per_page',25),10),100))]);}
    public function storeRisk(Request $r,AuthorizationService $a,ProcurementNumberService $numbers,AuditLogger $audit):JsonResponse{$d=$r->validate(['company_id'=>'required|uuid','supplier_id'=>'required|uuid','category'=>'required|in:delivery,quality,financial,contractual,compliance,operational_dependency,information_security','assessment_period'=>'nullable|string|max:80','description'=>'required|string|max:5000','likelihood'=>'required|in:rare,unlikely,possible,likely,almost_certain','impact'=>'required|in:low,moderate,high,severe','existing_controls'=>'nullable|string|max:5000','evidence'=>'nullable|array','risk_owner_id'=>'nullable|uuid','mitigation_plan'=>'nullable|string|max:5000','review_due_date'=>'nullable|date']);$this->scope($r,$a,$d['company_id']);$level=$this->riskLevel($d['likelihood'],$d['impact']);$risk=SupplierRiskAssessment::create([...$d,'tenant_id'=>$this->tenant(),'number'=>$numbers->makeFor('SRA',$this->tenant(),$d['company_id'],null),'suggested_level'=>$level,'status'=>'draft','created_by'=>$r->user()->id]);$audit->record($r,'supplier_risk_assessment.created',$this->tenant(),$risk);return response()->json(['data'=>$risk],201);}
    public function approveRisk(Request $r,SupplierRiskAssessment $risk,AuthorizationService $a,AuditLogger $audit):JsonResponse{abort_unless($risk->tenant_id===$this->tenant(),404);$this->scope($r,$a,$risk->company_id);abort_unless(in_array($risk->status,['draft','pending_review'],true),422);$d=$r->validate(['final_level'=>'required|in:low,medium,high,critical','override_reason'=>'nullable|string|max:4000']);if($d['final_level']!==$risk->suggested_level)abort_unless(!empty($d['override_reason']),422,'A reason is required for a risk-level override.');$risk->update(['final_level'=>$d['final_level'],'override_reason'=>$d['override_reason']??null,'status'=>'approved','reviewer_id'=>$r->user()->id,'approved_at'=>now()]);$audit->record($r,'supplier_risk_assessment.approved',$this->tenant(),$risk,['override'=>$d['final_level']!==$risk->suggested_level]);return response()->json(['data'=>$risk]);}
    public function compliance(Request $r,Supplier $supplier,AuthorizationService $a):JsonResponse{$this->supplier($r,$supplier,$a,$r->string('company_id')->toString()?:null);$company=$r->string('company_id')->toString()?:$supplier->company_id;$req=SupplierDocumentRequirement::where('tenant_id',$this->tenant())->where('company_id',$company)->where('is_active',true)->where(fn($q)=>$q->whereNull('supplier_type')->orWhere('supplier_type',$supplier->supplier_type))->get();$docs=SupplierDocument::where('tenant_id',$this->tenant())->where('company_id',$company)->where('supplier_id',$supplier->id)->get();$verified=$docs->where('status','verified');$missing=$req->filter(fn($x)=>$x->is_required&&!$verified->where('document_type',$x->name)->count())->values();$expired=$verified->filter(fn($x)=>$x->expiry_date&&$x->expiry_date->isPast());$status=$missing->isNotEmpty()||$expired->isNotEmpty()?'action_required':($req->isEmpty()?'insufficient_evidence':'requirements_met');return response()->json(['data'=>['supplier'=>$supplier,'status'=>$status,'required_count'=>$req->where('is_required',true)->count(),'verified_count'=>$verified->count(),'missing'=>$missing,'expired'=>$expired->values(),'documents'=>$docs->makeHidden(['storage_path'])]]);}
    public function actions(Request $r,AuthorizationService $a):JsonResponse{[$t,$ids]=$this->scope($r,$a,$r->string('company_id')->toString()?:null);$q=SupplierCorrectiveAction::where('tenant_id',$t)->with('supplier')->when(is_array($ids),fn($x)=>$x->whereIn('company_id',$ids))->when($r->filled('status'),fn($x)=>$x->where('status',$r->string('status')))->latest();return response()->json(['data'=>$q->paginate(min(max($r->integer('per_page',25),10),100))]);}
    public function storeAction(Request $r,AuthorizationService $a,ProcurementNumberService $numbers,AuditLogger $audit):JsonResponse{$d=$r->validate(['company_id'=>'required|uuid','supplier_id'=>'required|uuid','evaluation_id'=>'nullable|uuid','risk_assessment_id'=>'nullable|uuid','issue_description'=>'required|string|max:5000','root_cause'=>'nullable|string|max:5000','proposed_action'=>'required|string|max:5000','owner_id'=>'nullable|uuid','due_date'=>'nullable|date','priority'=>'required|in:low,medium,high,critical']);$this->scope($r,$a,$d['company_id']);$x=SupplierCorrectiveAction::create([...$d,'tenant_id'=>$this->tenant(),'number'=>$numbers->makeFor('SCA',$this->tenant(),$d['company_id'],null),'status'=>'open','created_by'=>$r->user()->id]);$audit->record($r,'supplier_corrective_action.created',$this->tenant(),$x);return response()->json(['data'=>$x],201);}
    public function updateAction(Request $r,SupplierCorrectiveAction $action,AuthorizationService $a,AuditLogger $audit):JsonResponse{abort_unless($action->tenant_id===$this->tenant(),404);$this->scope($r,$a,$action->company_id);$d=$r->validate(['status'=>'sometimes|in:open,in_progress,pending_verification,completed,reopened,cancelled','review_notes'=>'nullable|string|max:5000','due_date'=>'nullable|date']);if(($d['status']??null)==='completed')abort_unless($action->status==='pending_verification',422,'Corrective actions require verification before completion.');$action->update($d);$audit->record($r,'supplier_corrective_action.updated',$this->tenant(),$action);return response()->json(['data'=>$action]);}
    public function holds(Request $r,AuthorizationService $a):JsonResponse{[$t,$ids]=$this->scope($r,$a,$r->string('company_id')->toString()?:null);$q=SupplierPurchasingHold::where('tenant_id',$t)->with('supplier')->where('status','active')->when(is_array($ids),fn($x)=>$x->whereIn('company_id',$ids));return response()->json(['data'=>$q->paginate(25)]);}
    public function applyHold(Request $r,AuthorizationService $a,AuditLogger $audit):JsonResponse{$d=$r->validate(['company_id'=>'required|uuid','supplier_id'=>'required|uuid','type'=>'required|in:review,additional_approval,temporary_hold','reason'=>'required|string|min:2|max:4000','effective_from'=>'required|date','review_due_date'=>'nullable|date|after_or_equal:effective_from']);$this->scope($r,$a,$d['company_id']);$x=SupplierPurchasingHold::create([...$d,'tenant_id'=>$this->tenant(),'status'=>'active','applied_by'=>$r->user()->id]);$audit->record($r,'supplier_purchasing_hold.applied',$this->tenant(),$x);return response()->json(['data'=>$x],201);}
    public function releaseHold(Request $r,SupplierPurchasingHold $hold,AuthorizationService $a,AuditLogger $audit):JsonResponse{abort_unless($hold->tenant_id===$this->tenant(),404);$this->scope($r,$a,$hold->company_id);$d=$r->validate(['release_reason'=>'required|string|min:2|max:4000']);abort_unless($hold->status==='active',422);$hold->update(['status'=>'released','released_by'=>$r->user()->id,'released_at'=>now(),'release_reason'=>$d['release_reason']]);$audit->record($r,'supplier_purchasing_hold.released',$this->tenant(),$hold);return response()->json(['data'=>$hold]);}
    public function compare(Request $r,AuthorizationService $a):JsonResponse{$company=$r->string('company_id')->toString()?:null;[$t,$ids]=$this->scope($r,$a,$company);$supplierIds=$r->input('supplier_ids',[]);abort_unless(is_array($supplierIds)&&count($supplierIds)>=2&&count($supplierIds)<=10,422);$rows=SupplierPerformanceEvaluation::where('tenant_id',$t)->whereIn('supplier_id',$supplierIds)->where('status','approved')->when(is_array($ids),fn($q)=>$q->whereIn('company_id',$ids))->with(['supplier','metrics'])->latest('period_to')->get()->groupBy('supplier_id')->map(fn($set)=>$set->first());return response()->json(['data'=>$rows->values(),'metric_definitions'=>['scores'=>'Approved evaluation snapshots only; missing metrics remain unavailable.']]);}
    private function aggregate(string $t,?array $ids,string $metric):?float{$q=SupplierPerformanceMetricResult::where('tenant_id',$t)->where('metric',$metric)->where('available',true)->whereHas('evaluation',fn($x)=>$x->where('status','approved')->when(is_array($ids),fn($z)=>$z->whereIn('company_id',$ids)))->get();return $q->isEmpty()?null:round($q->avg('score'),2);}
    private function riskLevel(string $likelihood,string $impact):string{$l=['rare'=>1,'unlikely'=>2,'possible'=>3,'likely'=>4,'almost_certain'=>5][$likelihood];$i=['low'=>1,'moderate'=>2,'high'=>3,'severe'=>4][$impact];$score=$l*$i;return $score>=16?'critical':($score>=10?'high':($score>=5?'medium':'low'));}
    private function metricData(string $supplier,string $company,string $from,string $to):array
    {
        $orders=PurchaseOrder::where('tenant_id',$this->tenant())->where('company_id',$company)->where('supplier_id',$supplier)->whereIn('state',['approved','partially_received','received','closed'])->whereBetween('order_date',[$from,$to])->with('items')->get();$poIds=$orders->pluck('id');$receipts=GoodsReceipt::where('tenant_id',$this->tenant())->where('company_id',$company)->whereIn('purchase_order_id',$poIds)->where('state','posted')->whereBetween('receipt_date',[$from,$to])->with('items','purchaseOrder')->get();$ordered=(float)$orders->flatMap->items->sum('ordered_quantity');$accepted=(float)$receipts->flatMap->items->sum('accepted_quantity');$received=(float)$receipts->flatMap->items->sum('quantity');$returns=PurchaseReturn::where('tenant_id',$this->tenant())->whereIn('purchase_order_id',$poIds)->where('state','dispatched')->with('items')->get();$returned=(float)$returns->flatMap->items->sum('quantity');$onTime=$receipts->filter(fn($x)=>$x->purchaseOrder?->expected_at&&$x->receipt_date&&$x->receipt_date->lte($x->purchaseOrder->expected_at))->count();$deliveryDen=$receipts->filter(fn($x)=>$x->purchaseOrder?->expected_at&&$x->receipt_date)->count();$qualityDen=$receipts->flatMap->items->sum(fn($x)=>(float)$x->accepted_quantity+(float)$x->rejected_quantity+(float)$x->damaged_quantity);return ['on_time_delivery'=>['score'=>$deliveryDen?round($onTime/$deliveryDen*100,4):null,'numerator'=>$onTime,'denominator'=>$deliveryDen,'sample_size'=>$deliveryDen,'available'=>$deliveryDen>0,'methodology'=>'Posted receipts with comparable expected and receipt dates.','source_references'=>$receipts->pluck('id')->values()->all()],'quality_acceptance'=>['score'=>$qualityDen?round($accepted/$qualityDen*100,4):null,'numerator'=>$accepted,'denominator'=>$qualityDen,'sample_size'=>$qualityDen>0?1:0,'available'=>$qualityDen>0,'methodology'=>'Accepted inspected quantity divided by accepted, rejected and damaged quantity.','source_references'=>$receipts->flatMap->items->pluck('id')->values()->all()],'fulfillment'=>['score'=>$ordered?round($accepted/$ordered*100,4):null,'numerator'=>$accepted,'denominator'=>$ordered,'sample_size'=>$orders->count(),'available'=>$ordered>0,'methodology'=>'Accepted posted receipt quantity divided by eligible ordered quantity.','source_references'=>$poIds->values()->all()],'return_rate'=>['score'=>$received?round($returned/$received*100,4):null,'numerator'=>$returned,'denominator'=>$received,'sample_size'=>$returns->count(),'available'=>$received>0,'methodology'=>'Dispatched return quantity divided by posted received quantity.','source_references'=>$returns->pluck('id')->values()->all()],'price_variance'=>['score'=>null,'numerator'=>null,'denominator'=>null,'sample_size'=>0,'available'=>false,'methodology'=>'Unavailable until posted bill and agreed-price sources are comparable.','source_references'=>[]]];}
}
